import { join, normalize } from '@angular-devkit/core';
import type { Tree } from '@angular-devkit/schematics';

export function topicsFilePath(sourceRoot: string): string {
  return join(normalize(sourceRoot), 'kafka', 'kafka.topics.ts');
}

/**
 * Ensures `topic` is in the `KafkaTopics` map generated by `nest add` and
 * returns its key, or `null` when there is no topics file to add it to.
 * An existing entry for the same topic is reused whatever its key.
 */
export function ensureTopic(
  tree: Tree,
  sourceRoot: string,
  key: string,
  topic: string,
): string | null {
  const path = topicsFilePath(sourceRoot);
  if (!tree.exists(path)) {
    return null;
  }
  const content = tree.readText(path);
  const body = /export const KafkaTopics = \{([\s\S]*?)\} as const;/.exec(
    content,
  );
  if (!body) {
    return null;
  }

  const entries = [...body[1].matchAll(/(\w+)\s*:\s*['"]([^'"]+)['"]/g)];
  const sameTopic = entries.find(([, , value]) => value === topic);
  if (sameTopic) {
    return sameTopic[1];
  }
  let uniqueKey = key;
  for (let n = 2; entries.some(([, existing]) => existing === uniqueKey); n++) {
    uniqueKey = `${key}_${n}`;
  }

  const insertAt = body.index + body[0].lastIndexOf('}');
  let before = content.slice(0, insertAt).replace(/\s*$/, '');
  if (!before.endsWith(',') && !before.endsWith('{')) {
    before += ',';
  }
  const entry = `\n  ${uniqueKey}: '${topic}',\n`;
  tree.overwrite(path, before + entry + content.slice(insertAt));
  return uniqueKey;
}
